package com.kai.automusic;
import android.content.*;import android.graphics.*;import android.view.*;import android.media.audiofx.Visualizer;import android.os.*;
public class Spectrum extends View {
 final Paint paint=new Paint(3); final float[] levels=new float[31],smooth=new float[31]; final Handler h=new Handler(Looper.getMainLooper()); byte[] wave=new byte[0]; Visualizer vis; int session=-1; boolean running=false;
 public Spectrum(Context c){super(c);setContentDescription("กราฟความถี่เสียงเพลง 31 แบนด์");}
 void start(){if(running)return;running=true;h.post(tick);}
 void stop(){running=false;h.removeCallbacks(tick);close();}
 void close(){if(vis!=null){try{vis.release();}catch(Exception e){}vis=null;}session=-1;synchronized(levels){java.util.Arrays.fill(levels,0);}}
 final Runnable tick=new Runnable(){public void run(){if(!running)return;android.content.SharedPreferences p=getContext().getSharedPreferences("music",0);int id=p.getInt("audioSession",-1);if(id!=session){close();session=id;if(id>0)try{vis=new Visualizer(id);int[] range=Visualizer.getCaptureSizeRange();vis.setCaptureSize(range[1]);vis.setDataCaptureListener(new Visualizer.OnDataCaptureListener(){public void onWaveFormDataCapture(Visualizer v,byte[] b,int rate){wave=b.clone();}public void onFftDataCapture(Visualizer v,byte[] b,int rate){synchronized(levels){for(int i=0;i<31;i++){double f=20*Math.pow(2,i/3.0);int lo=Math.max(1,(int)Math.floor(f/Math.pow(2,1.0/6)*b.length/(rate/1000.0)));int hi=Math.min(b.length/2-1,Math.max(lo,(int)Math.ceil(f*Math.pow(2,1.0/6)*b.length/(rate/1000.0))));double peak=0;for(int k=lo;k<=hi;k++)peak=Math.max(peak,Math.hypot(b[2*k],b[2*k+1]));levels[i]=(float)Math.max(0,Math.min(1,(20*Math.log10(Math.max(1,peak))-4)/38));}}}},Math.min(Visualizer.getMaxCaptureRate(),15000),true,true);vis.setEnabled(true);}catch(Exception e){close();session=id;}}boolean playing=p.getBoolean("playing",false);synchronized(levels){for(int i=0;i<31;i++){float target=playing?levels[i]:0;smooth[i]=Math.max(target,smooth[i]*.84f);}}invalidate();h.postDelayed(this,65);}};
 protected void onDraw(Canvas c){super.onDraw(c);float w=getWidth(),height=getHeight(),base=height-13,step=w/31f;if(getContext().getSharedPreferences("music",0).getBoolean("wave",false)){byte[] b=wave;paint.setColor(0xff38bdf8);paint.setStrokeWidth(1.5f);for(int i=1;i<b.length;i++)c.drawLine((i-1)*w/b.length,height/2+((b[i-1]&255)-128)*height/256,i*w/b.length,height/2+((b[i]&255)-128)*height/256,paint);return;}paint.setColor(0xff101722);paint.setShader(new LinearGradient(0,0,0,base,new int[]{0xfff87171,0xfffbbf24,0xff34d399,0xff38bdf8},null,Shader.TileMode.CLAMP));for(int i=0;i<31;i++){float x=i*step+1; c.drawRoundRect(x,base-Math.max(1,smooth[i]*(base-3)),x+Math.max(1,step-2),base,2,2,paint);}paint.setShader(null);paint.setColor(0xffaab8c8);paint.setTextSize(10);c.drawText(vis==null?"RTA • ไม่พร้อมใช้งาน":"RTA • 20 Hz – 20 kHz",4,height-2,paint);}
}